// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ChatGenerationRun) predicate.ChatGenerationRun {
	return predicate.ChatGenerationRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ChatGenerationRun) predicate.ChatGenerationRun {
	return predicate.ChatGenerationRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ChatGenerationRun) predicate.ChatGenerationRun {
	return predicate.ChatGenerationRun(sql.NotPredicates(p))
}
